import { vi } from 'vitest';

describe('Mocking', () => {
  it('mocks functions', () => {
    const mockFn = vi.fn().mockReturnValue(42);
    expect(mockFn()).toBe(42);
    expect(mockFn).toHaveBeenCalled();
  });

  it('spies on methods', () => {
    const obj = {
      method: () => 'original'
    };
    const spy = vi.spyOn(obj, 'method').mockReturnValue('mocked');
    expect(obj.method()).toBe('mocked');
    spy.mockRestore();
  });
});
